let w = WindTurbineTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, power_mw) by turbine_id | summarize v=sum(power_mw);
let s = SolarInverterTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, power_kw) by inverter_id | summarize v=sum(power_kw)/1000.0;
let g = EmissionsStream | where timestamp > ago(5m) | summarize arg_max(timestamp, power_output_mw) by plant_id | summarize v=sum(power_output_mw);
let total = toscalar(w) + toscalar(s) + toscalar(g);
let freq = GridTelemetry | where grid_id == 'GR-MAIN' and timestamp > ago(2m) | top 1 by timestamp desc | project v=frequency_hz;
let co2 = EmissionsStream | where timestamp > ago(5m) | summarize arg_max(timestamp, co2_kg_per_hour) by plant_id | summarize v=sum(co2_kg_per_hour)/1000.0;
let ci = iff(total > 0, toscalar(co2)*1000.0/total, 0.0);
print Total_MW = round(total, 1), Wind_MW = round(toscalar(w), 1), Solar_MW = round(toscalar(s), 1), Gas_MW = round(toscalar(g), 1), Renewable_Pct = round(100.0*(toscalar(w)+toscalar(s))/total, 1), Mainland_Hz = round(toscalar(freq), 3), CO2_tph = round(toscalar(co2), 2), Carbon_gCO2_kWh = round(ci, 1)

let w = WindTurbineTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, power_mw) by turbine_id | summarize MW = round(sum(power_mw), 1) | extend Source = 'Wind';
let s = SolarInverterTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, power_kw) by inverter_id | summarize MW = round(sum(power_kw)/1000.0, 1) | extend Source = 'Solar';
let g = EmissionsStream | where timestamp > ago(5m) | summarize arg_max(timestamp, power_output_mw) by plant_id | summarize MW = round(sum(power_output_mw), 1) | extend Source = 'Gas';
union w, s, g | project Source, MW

let vib_alerts = WindTurbineTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, vibration_mm_s, nacelle_temp_c, power_mw) by turbine_id | where vibration_mm_s > 4.0 or nacelle_temp_c > 70 | extend Alert = strcat(turbine_id, iff(vibration_mm_s > 4.0, strcat(' Vibration=', tostring(round(vibration_mm_s, 1)), 'mm/s'), ''), iff(nacelle_temp_c > 70, strcat(' Temp=', tostring(round(nacelle_temp_c, 1)), 'C'), '')), Severity = iff(vibration_mm_s > 6.0 or nacelle_temp_c > 80, 'CRITICAL', 'Warning'), Source = 'Wind';
let grid_alerts = GridTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, frequency_hz, voltage_kv) by grid_id, grid_name | where frequency_hz < 49.85 or frequency_hz > 50.15 | extend Alert = strcat(grid_name, ' Freq=', tostring(round(frequency_hz, 3)), 'Hz'), Severity = iff(frequency_hz < 49.7 or frequency_hz > 50.3, 'CRITICAL', 'Warning'), Source = 'Grid';
let ets_alerts = EmissionsStream | where timestamp > ago(5m) | summarize arg_max(timestamp, compliance_pct) by plant_id, plant_name | where compliance_pct > 80 | extend Alert = strcat(plant_name, ' ETS Usage=', tostring(round(compliance_pct, 0)), '%'), Severity = iff(compliance_pct > 95, 'CRITICAL', 'Warning'), Source = 'Emissions';
union (vib_alerts | project Severity, Source, Alert), (grid_alerts | project Severity, Source, Alert), (ets_alerts | project Severity, Source, Alert) | order by Severity asc

let w = WindTurbineTelemetry | where timestamp > ago(30m) | summarize MW = round(sum(power_mw), 1) by bin(timestamp, 30s) | extend Source = 'Wind';
let s = SolarInverterTelemetry | where timestamp > ago(30m) | summarize MW = round(sum(power_kw)/1000.0, 1) by bin(timestamp, 30s) | extend Source = 'Solar';
let g = EmissionsStream | where timestamp > ago(30m) | summarize MW = round(sum(power_output_mw), 1) by bin(timestamp, 30s) | extend Source = 'Gas';
union w, s, g | project timestamp, Source, MW | order by timestamp asc

let gen = WindTurbineTelemetry | where timestamp > ago(30m) | summarize wind_mw = sum(power_mw) by bin(timestamp, 30s);
let sol = SolarInverterTelemetry | where timestamp > ago(30m) | summarize solar_mw = sum(power_kw)/1000.0 by bin(timestamp, 30s);
let gas = EmissionsStream | where timestamp > ago(30m) | summarize gas_mw = sum(power_output_mw), co2_kgh = sum(co2_kg_per_hour) by bin(timestamp, 30s);
gen | join kind=leftouter sol on timestamp | join kind=leftouter gas on timestamp
| extend total_mw = wind_mw + coalesce(solar_mw, 0.0) + coalesce(gas_mw, 0.0)
| extend gCO2_kWh = iff(total_mw > 0, round(coalesce(co2_kgh, 0.0) / total_mw, 1), 0.0)
| project timestamp, gCO2_kWh
| order by timestamp asc

let mw = SolarInverterTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, power_kw) by inverter_id | summarize v=sum(power_kw)/1000.0;
let ghi = SolarInverterTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, irradiance_wm2) by inverter_id | summarize v=avg(irradiance_wm2);
let tmp = SolarInverterTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, panel_temp_c) by inverter_id | summarize v=avg(panel_temp_c);
let eff = SolarInverterTelemetry | where timestamp > ago(2m) and irradiance_wm2 > 50 | summarize arg_max(timestamp, efficiency_pct) by inverter_id | summarize v=avg(efficiency_pct);
let cap = 140.0;
print Solar_MW = round(toscalar(mw), 1), Capacity_MW = cap, CF_Pct = round(100.0*toscalar(mw)/cap, 1), Irradiance_Wm2 = round(toscalar(ghi), 0), Panel_Temp_C = round(toscalar(tmp), 1), Efficiency_Pct = round(toscalar(eff), 1)

let gen = WindTurbineTelemetry | where timestamp > ago(30m) | summarize wind_mw = sum(power_mw) by bin(timestamp, 30s);
let sol = SolarInverterTelemetry | where timestamp > ago(30m) | summarize solar_mw = sum(power_kw)/1000.0 by bin(timestamp, 30s);
let gas = EmissionsStream | where timestamp > ago(30m) | summarize gas_mw = sum(power_output_mw), co2_kgh = sum(co2_kg_per_hour) by bin(timestamp, 30s);
gen | join kind=leftouter sol on timestamp | join kind=leftouter gas on timestamp
| extend total_mw = wind_mw + coalesce(solar_mw, 0.0) + coalesce(gas_mw, 0.0)
| extend gCO2_kWh = iff(total_mw > 0, round(coalesce(co2_kgh, 0.0) / total_mw, 1), 0.0)
| project timestamp, gCO2_kWh
| order by timestamp asc

let freq = GridTelemetry | where grid_id == 'GR-MAIN' and timestamp > ago(2m) | top 1 by timestamp desc | project v = frequency_hz;
let demand = GridTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, load_mw) by grid_id | summarize v=sum(load_mw);
let gen = GridTelemetry | where timestamp > ago(2m) | summarize arg_max(timestamp, generation_mw) by grid_id | summarize v=sum(generation_mw);
let bal = toscalar(gen) - toscalar(demand);
let reserve = iff(toscalar(demand) > 0, round(100.0 * bal / toscalar(demand), 1), 0.0);
print Mainland_Hz = round(toscalar(freq), 3), Total_Demand_MW = round(toscalar(demand), 0), Total_Gen_MW = round(toscalar(gen), 0), Balance_MW = round(bal, 1), Reserve_Margin_Pct = reserve
